    {% set current_copy = "ORIGINAL" %} 
{% elif copy_name_param %}
    {% set current_copy = copy_name_param %}
{% else %}
    {% set current_copy = "ORIGINAL" %}
{% endif %}

<div style="position: relative; width: 100%; ">

