        top: 0px; 
        right: 0px; 
        border: 2px solid #000; 
        width:135px;
        position:absolute;
        padding:5px;
        font-weight: bold; 
        font-size: 12px; 
        text-transform: uppercase;
        margin-top:8px;
        background-color: #fff; /* Optional: keeps text clear */
    ">
        {{ current_copy }}
    </div>

