<style>
    .main-info-table {
        width: 100%;
        border-collapse: collapse;
        font-family: Arial, sans-serif;
        font-size: 11px; /* Match screenshot size */
        border: 1px solid #000; /* Outer border */
    }
    .left-col {
        width: 50%;
        vertical-align: top;
        padding: 8px;
        border-right: 1px solid #000; /* The Vertical Divider */
    }
    .right-col {
        width: 50%;
        vertical-align: top;
        padding: 8px;
    }
    .right-data-table {
        width: 100%;
        border-collapse: collapse;
    }
    .right-data-table td {
        padding: 4px 2px;
        vertical-align: top;
    }
    .lbl {
        font-weight: bold;
        width: 22%;
    }
    .val {
        width: 28%;
    }
    .copy-label {
        text-align: right; 
        font-weight: bold; 
        font-size: 10px; 
        text-transform: uppercase; 
        margin-bottom: 5px;
    }
</style>

<table class="main-info-table">
    <tr>
        <!-- LEFT SIDE: Customer & Delivery Details -->
        <td class="left-col">
            <!-- Customer Name -->
            <div style="font-size:12px; font-weight:bold; margin-bottom:4px;">
                M/s. {{ doc.customer_name }}
            </div>

            <!-- Address -->
            <div style="line-height:1.4; margin-bottom:8px;">
                {{ doc.address_display or "" }}
            </div>

            <!-- Billing GST -->
            <div style="margin-bottom:8px;">
                <strong>G.S.T. :</strong> {{ doc.billing_address_gstin or "" }}
            </div>

            <!-- Dashed Separator -->
            <div style="border-top: 1px dashed #000; margin: 8px 0; padding-top: 5px;"></div>

            <!-- Delivery Details -->
            <strong style="text-decoration: underline;">Delivery At :</strong>
            <div style="margin-top:4px; line-height:1.4;">
                {{ doc.shipping_address_display or doc.address_display or "" }}
            </div>

            {% if doc.contact_mobile %}
            <div style="margin-top:6px; font-weight:bold;">
                Mob: {{ doc.contact_mobile }}
            </div>
            {% endif %}
        </td>

        <!-- RIGHT SIDE: Invoice Metadata -->
        <td class="right-col">

            <!-- Show Copy Name (Original/Duplicate) Top Right -->

            <table class="right-data-table">
                <!-- Row 1: Invoice No & Date -->

                <!-- Row 2: Order Info -->
                <tr>
                    <td class="lbl">Order No.</td>
                    <td class="val">: {{ doc.po_no or "" }}</td>
                    <td class="lbl">Order Date</td>
                    <td class="val">: {{ frappe.utils.formatdate(doc.po_date) if doc.po_date else "" }}</td>
                </tr>

                <!-- Row 3: DC Info -->
                <tr>
                    <td class="lbl">D.C. No.</td>
                    <td class="val">: {{ doc.delivery_note or "" }}</td>
                    <td class="lbl">D.C. Date</td>
                    <td class="val">: {{ frappe.utils.formatdate(doc.delivery_date) if doc.delivery_date else "" }}</td>
                </tr>

                <!-- Row 4: Boxes & Due Date -->
                <tr>
                    <td class="lbl">Total Boxes</td>
                    <td class="val">: {{ doc.custom_no_of_boxes__bundles or "" }}</td>
                    <td class="lbl">Due Date</td>
                    <td class="val">: {{ frappe.utils.formatdate(doc.due_date) if doc.due_date else "" }}</td>
                </tr>

                <!-- Row 5: LR Info -->
                <tr>
                    <td class="lbl">L.R. No.</td>
                    <td class="val">: {{ doc.lr_no or "" }}</td>
                    <td class="lbl">L.R. Date</td>
                    <td class="val">: {{ frappe.utils.formatdate(doc.lr_date) if doc.lr_date else "" }}</td>
                </tr>

                <!-- Row 6: Transport -->
                <tr>
                    <td class="lbl">Transport</td>
                    <td class="val">: {{ doc.mode_of_transport or "" }}</td>
                    <td class="lbl">Vehicle No.</td>
                    <td class="val">: {{ doc.vehicle_no or "" }}</td>
