</table>"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "items", "print_hide": 0, "label": "Items", "visible_columns": [{"fieldname": "item_code", "print_width": "100px", "print_hide": 0}, {"fieldname": "description", "print_width": "200px", "print_hide": 0}, {"fieldname": "gst_hsn_code", "print_width": "50px", "print_hide": 0}, {"fieldname": "qty", "print_width": "50px", "print_hide": 0}, {"fieldname": "rate", "print_width": "90px", "print_hide": 0}, {"fieldname": "item_tax_template", "print_width": "100px", "print_hide": 0}, {"fieldname": "amount", "print_width": "80px", "print_hide": 0}]}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "{% set ns = namespace(total_discount=0.0) %}
