<div class="summary-area" style="border-top:1.5px solid #000; padding-top:5px; font-family: Arial, sans-serif; page-break-inside: avoid;">

    <!-- 1. MAIN SUMMARY TABLE (Tax Left / Financials Right) -->
    <table style="width:100%; border-collapse:collapse; table-layout: fixed;">
        <tr>
            <!-- LEFT COL: Qty & Tax Details -->
            <td style="width:60%; vertical-align:top; padding-right:15px;">

                <!-- Qty Box -->
                <table style="border-collapse: collapse; margin-bottom:10px; font-size:11px;">
                    <tr>
                        <td style="border:1px solid #ccc; padding: 3px 8px; background-color:#f8f8f8;">
                            <strong>Total Items:</strong> {{ doc.total_qty | int }}
                        </td>
                        {% if doc.custom_no_of_boxes__bundles %}
                        <td style="border:1px solid #ccc; border-left:none; padding: 3px 8px;">
                            <strong>Total Boxes:</strong> {{ doc.custom_no_of_boxes__bundles }}
                        </td>
                        {% endif %}
                    </tr>
                </table>

                <!-- Tax/HSN Breakup Table -->
                <div style="color:#333; width:100%; font-size:11px;">
                    {{ doc.other_charges_calculation or "" }}
                </div>
            </td>

            <!-- RIGHT COL: Financials + BANK DETAILS -->
            <td style="width:40%; vertical-align:top;">
                <table style="width:100%; border-collapse:collapse; font-size:11px;">
                    <tr>
                        <td style="padding:2px 0;">Sub Total</td>
                        <td style="padding:2px 0; text-align:right; font-weight:bold;">
                            {{ "{:,.2f}".format(doc.net_total + ns.total_discount) }}
                        </td>
                    </tr>

                    {% if ns.total_discount > 0 %}
                    <tr>
                        <td style="padding:2px 0;">Total Discount</td>
                        <td style="padding:2px 0; text-align:right; font-weight:bold;">
                            - {{ "{:,.2f}".format(ns.total_discount) }}
                        </td>
                    </tr>
                    {% endif %}

                    {% for tax in doc.taxes %}
                        {% if tax.tax_amount != 0 %}
                        <tr>
                            <td style="padding:2px 0;">{{ tax.account_head.split(' - ')[0] }}</td>
                            <td style="padding:2px 0; text-align:right; font-weight:bold;">
                                {{ "{:,.2f}".format(tax.tax_amount) }}
                            </td>
                        </tr>
                        {% endif %}
                    {% endfor %}

                    <tr>
                        <td style="padding:2px 0;">Round Off</td>
                        <td style="padding:2px 0; text-align:right; font-weight:bold;">
                            {{ "{:,.2f}".format(doc.rounding_adjustment or 0.00) }}
                        </td>
                    </tr>

                    <tr style="border-top:1.5px solid #000; border-bottom:1.5px solid #000; background-color:#f9f9f9;">
                        <td style="padding:5px 2px; font-weight:bold; font-size:14px;">Total ₹</td>
                        <td style="padding:5px 2px; text-align:right; font-weight:bold; font-size:14px;">
                            {{ "{:,.2f}".format(doc.rounded_total or doc.grand_total) }}
                        </td>
                    </tr>
                </table>

                <!-- BANK DETAILS -->
                {% set company_doc = frappe.get_doc("Company", doc.company) %}
                {% if company_doc.bank_details_for_printing %}
                <table style="width:100%; margin-top:10px; border:1px solid #ccc; border-collapse:collapse; font-size:11px;">
                    <tr style="background-color:#eee;">
                        <td colspan="2" style="padding:3px; text-align:center; font-weight:bold; border-bottom:1px solid #ccc; text-transform: uppercase;">
                            Bank Details
                        </td>
                    </tr>
                    {% for d in company_doc.bank_details_for_printing %}
                        {% if d.print_label %}
                        <tr>
                            <td style="padding:2px 4px; border-bottom:1px solid #eee; width:40%;">{{ d.print_label }}</td>
                            <td style="padding:2px 4px; border-bottom:1px solid #eee; font-weight:bold;">{{ d.print_value }}</td>
                        </tr>
                        {% endif %}
                    {% endfor %}
                </table>
                {% endif %}
            </td>
        </tr>
    </table>

    <!-- 2. AMOUNT IN WORDS -->
    <div style="border:1px solid #000;  padding:5px 8px; background-color:#fafafa; font-size:11px;">
         <strong>Amount in Words:</strong> 
         <span style="font-style:italic; font-weight:bold; margin-left:5px;">
            Rupees {{ frappe.utils.money_in_words(doc.rounded_total or doc.grand_total) }} Only
         </span>
    </div>

    <!-- 3. FOOTER: Terms & Signature -->
    <table style="width:100%; border:1px solid #000; border-top:none; border-collapse:collapse;">
        <tr>
            <!-- Left Side: Terms -->
            <td style="width:60%; vertical-align:top; padding:10px; font-size:11px; border-right:1px solid #000;">
                {% if doc.remarks %}
                    <div style="margin-bottom:8px;"><strong>Remarks:</strong> {{ doc.remarks }}</div>
                {% endif %}

                {% if doc.terms %}
                    <strong>Terms & Conditions:</strong>
                    <div style="margin-top:4px; line-height:1.4;">{{ doc.terms | safe }}</div>
                {% endif %}
            </td>

            <!-- Right Side: Signatory -->
            <!-- Right Side: Signatory -->
            <td style="width:40%; vertical-align:top; text-align:center; padding:10px;">

                <!-- Top Text -->
                <div style="font-size:11px; font-weight:bold; margin-bottom: 140px;">
                    For {{ doc.company }}
                </div>

                <!-- This space (100px) is where the signature and stamp will go -->

                <!-- Signature Line -->
                <div style="display:inline-block; border-top:1px solid #000; padding-top:5px; width:80%; font-weight:bold; font-size:11px; ">
                    Authorised Signatory
                </div>

            </td>
        </tr>
    </table>
</div>"}]
